private enum PostTypeStylePalette {
    static func color(for postType: String) -> Color {
        switch postType {
        case "Text":
            return Color(red: 0.20, green: 0.22, blue: 0.26)
        case "Photo", "Photo/Video":
            return Color(red: 0.17, green: 0.38, blue: 0.78)
        case "Video":
            return Color(red: 0.54, green: 0.22, blue: 0.82)
        case "Link":
            return Color(red: 0.09, green: 0.58, blue: 0.35)
        case "Audio", "Song":
            return Color(red: 0.09, green: 0.45, blue: 0.78)
        case "Poll":
            return Color(red: 0.63, green: 0.21, blue: 0.70)
        case "Live Route":
            return Color(red: 0.10, green: 0.62, blue: 0.53)
        case "Guide":
            return Color(red: 0.74, green: 0.54, blue: 0.08)
        case "Work", "Hiring":
            return Color(red: 0.14, green: 0.28, blue: 0.62)
        case "For Sale":
            return Color(red: 0.79, green: 0.39, blue: 0.15)
        default:
            return .black
        }
    }
}

private enum MapFocusMode {
    case recentBalanced
    case nearbyRecent
    case userLocation
    case newestOnly
}

struct MapPostMarker: Identifiable {
    let id: String
    let postID: Int
    let type: String
    let locationName: String
    let coordinate: CLLocationCoordinate2D
    let createdAt: Date
    let hasPreciseCoordinate: Bool
}

private struct MapPostTypeShellIcon: View {
    let postType: String

    private var symbolName: String {
        switch postType {
        case "Text": return "text.alignleft"
        case "Photo": return "photo.fill"
        case "Video": return "play.fill"
        case "Photo/Video": return "photo.on.rectangle.angled"
        case "Link": return "link"
        case "Audio": return "waveform"
        case "Song": return "music.note"
        case "Poll": return "chart.pie.fill"
        case "Live Route": return "point.topleft.down.curvedto.point.bottomright.up"
        case "Guide": return "list.number"
        case "Work", "Hiring": return "briefcase.fill"
        case "For Sale": return "tag.fill"
        default: return "mappin.and.ellipse"
        }
    }

    private var tint: Color {
        PostTypeStylePalette.color(for: postType)
    }

    private var borderTint: Color {
        PostTypeStylePalette.color(for: postType)
    }

    var body: some View {
        Image(systemName: symbolName)
            .font(.system(size: 8, weight: .bold))
            .foregroundStyle(tint)
    }
}

private struct MapPostFreshnessHaloIcon: View {
    let postID: Int
    let postType: String
    let createdAt: Date
    let currentZoom: CGFloat
    let showsIsolatedPulse: Bool
    // At the minimum zoom, this starts large and then shrinks over one minute.
    private let startDiameterAtReferenceZoom: CGFloat = 220.0
    private let referenceZoom: CGFloat = 13.8
    private let haloDurationSeconds: TimeInterval = 120.0
    private let isolatedPulseCycleSeconds: TimeInterval = 1.45
    private let isolatedPulseMinDiameter: CGFloat = 8.0
    private let isolatedPulseMaxDiameter: CGFloat = 16.0
    private static let firstSeenDefaultsKey = "spot_map_marker_first_seen_epoch_by_post_id"
    private static var firstSeenEpochByPostID: [String: TimeInterval] = {
        UserDefaults.standard.dictionary(forKey: firstSeenDefaultsKey) as? [String: Double] ?? [:]
    }()

    @State private var anchoredCreatedAt: Date? = nil

    private static func persistedFirstSeenDate(for postID: Int, createdAt: Date) -> Date {
        let key = String(postID)
        let nowEpoch = Date().timeIntervalSince1970
        let candidateEpoch = min(createdAt.timeIntervalSince1970, nowEpoch)

        if let existingEpoch = firstSeenEpochByPostID[key] {
            let resolvedEpoch = min(existingEpoch, candidateEpoch)
            if resolvedEpoch != existingEpoch {
                firstSeenEpochByPostID[key] = resolvedEpoch
                UserDefaults.standard.set(firstSeenEpochByPostID, forKey: firstSeenDefaultsKey)
            }
            return Date(timeIntervalSince1970: resolvedEpoch)
        }

        firstSeenEpochByPostID[key] = candidateEpoch
        UserDefaults.standard.set(firstSeenEpochByPostID, forKey: firstSeenDefaultsKey)
        return Date(timeIntervalSince1970: candidateEpoch)
    }

    private func remainingFraction(at date: Date, anchorDate: Date) -> CGFloat {
        let elapsed = max(0, date.timeIntervalSince(anchorDate))
        let progress = min(1.0, elapsed / haloDurationSeconds)
        return max(0, CGFloat(1.0 - progress))
    }

    private func zoomScale() -> CGFloat {
        let rawScale = CGFloat(pow(2.0, Double(currentZoom - referenceZoom)))
        return min(max(rawScale, 0.2), 24.0)
    }

    private func isolatedPulsePhase(at date: Date) -> CGFloat {
        let raw = date.timeIntervalSinceReferenceDate / isolatedPulseCycleSeconds
        let phase = raw - floor(raw)
        if phase < 0.5 {
            return CGFloat(phase * 2.0)
        }
        return CGFloat((1.0 - phase) * 2.0)
    }

    var body: some View {
        let anchor = anchoredCreatedAt ?? createdAt
        let now = Date()
        let remaining = remainingFraction(at: now, anchorDate: anchor)
        let diameter = startDiameterAtReferenceZoom * remaining * zoomScale()
        let pulsePhase = isolatedPulsePhase(at: now)
        let pulseDiameter = isolatedPulseMinDiameter + (isolatedPulseMaxDiameter - isolatedPulseMinDiameter) * pulsePhase

        ZStack {
            MapPostTypeShellIcon(postType: postType)
                .frame(width: 9, height: 9)
        }
        .overlay {
            if diameter > 0.1 {
                Circle()
                    .stroke(Color.black, lineWidth: 1.0)
                    .frame(width: diameter, height: diameter)
                    .opacity(Double(remaining))
                    .allowsHitTesting(false)
            }

            if showsIsolatedPulse && remaining <= 0.001 {
                Circle()
                    .stroke(Color.black.opacity(0.75), lineWidth: 0.85)
                    .frame(width: pulseDiameter, height: pulseDiameter)
                    .opacity(Double(0.35 + (0.45 * (1.0 - pulsePhase))))
                    .allowsHitTesting(false)
            }
        }
        .frame(width: 21, height: 21)
        .onAppear {
            anchoredCreatedAt = Self.persistedFirstSeenDate(for: postID, createdAt: createdAt)
        }
    }
}

private struct PostsMapView: View {
    let markers: [MapPostMarker]
    let focusedPostID: Int?
    let focusMode: MapFocusMode
    let focusTrigger: Int
    let userCoordinate: CLLocationCoordinate2D?
    let hideAttributionButton: Bool
    let mapTapEnabled: Bool
    let mapLongPressEnabled: Bool
    let onMapTap: (CLLocationCoordinate2D) -> Void
    let onMapLongPress: (CLLocationCoordinate2D) -> Void
    let onMarkerTap: (Int) -> Void
    let onCameraCenterZoomChanged: ((CLLocationCoordinate2D, CGFloat) -> Void)?

    private static let mapIconCollisionRadiusMiles: Double = 0.012

    @State private var region = MKCoordinateRegion(
        center: NearbyPlaceLoader.defaultCenter,
        span: MKCoordinateSpan(latitudeDelta: 0.12, longitudeDelta: 0.12)
    )

    var body: some View {
        Map(coordinateRegion: $region, annotationItems: nonOverlappingMarkers) { marker in
            MapAnnotation(coordinate: marker.coordinate) {
                Button {
                    onMarkerTap(marker.postID)
                } label: {
                    MapPostFreshnessHaloIcon(
                        postID: marker.postID,
                        postType: marker.type,
                        createdAt: marker.createdAt,
                        currentZoom: currentZoomEstimate,
                        showsIsolatedPulse: true
                    )
                    .frame(width: 21, height: 21)
                }
                .buttonStyle(.plain)
                .accessibilityLabel("\(marker.type) post in \(marker.locationName)")
            }
        }
        .onTapGesture {
            guard mapTapEnabled else { return }
            onMapTap(region.center)
        }
        .onLongPressGesture {
            guard mapLongPressEnabled else { return }
            onMapLongPress(region.center)
        }
        .onAppear {
            syncRegionToMarkers()
            onCameraCenterZoomChanged?(region.center, currentZoomEstimate)
        }
        .onChange(of: markers.map(\.id)) { _, _ in
            syncRegionToMarkers()
            onCameraCenterZoomChanged?(region.center, currentZoomEstimate)
        }
        .onChange(of: focusedPostID) { _, _ in
            syncRegionToMarkers()
            onCameraCenterZoomChanged?(region.center, currentZoomEstimate)
        }
        .onChange(of: focusTrigger) { _, _ in
            syncRegionToMarkers()
            onCameraCenterZoomChanged?(region.center, currentZoomEstimate)
        }
    }

    private var nonOverlappingMarkers: [MapPostMarker] {
        let prioritized = markers.sorted { lhs, rhs in
            if lhs.postID == focusedPostID { return true }
            if rhs.postID == focusedPostID { return false }
            if lhs.createdAt != rhs.createdAt {
                return lhs.createdAt > rhs.createdAt
            }
            return lhs.postID > rhs.postID
        }

        // Strict no-overlap rule: keep higher-priority markers and drop any that collide.
        let collisionRadius = collisionRadiusMilesForCurrentZoom
        var filtered: [MapPostMarker] = []
        filtered.reserveCapacity(prioritized.count)

        for candidate in prioritized {
            let collidesWithVisible = filtered.contains { visible in
                NearbyPlaceLoader.haversineMiles(from: visible.coordinate, to: candidate.coordinate) < collisionRadius
            }
            if collidesWithVisible {
                continue
            }
            filtered.append(candidate)
        }

        return filtered
    }

    private var collisionRadiusMilesForCurrentZoom: Double {
        let zoomOutProgress = min(max((16.0 - Double(currentZoomEstimate)) / 3.2, 0.0), 1.0)
        let spacingMultiplier = 1.0 + (zoomOutProgress * 1.35)
        return Self.mapIconCollisionRadiusMiles * spacingMultiplier
    }

    private var currentZoomEstimate: CGFloat {
        let span = max(region.span.latitudeDelta, region.span.longitudeDelta)
        switch span {
        case ..<0.02: return 16.0
        case ..<0.05: return 15.2
        case ..<0.12: return 14.1
        case ..<0.30: return 12.9
        case ..<0.80: return 11.1
        default: return 10.0
        }
    }

    private func syncRegionToMarkers() {
        if let focusedPostID,
           let focusedMarker = markers.first(where: { $0.postID == focusedPostID }) {
            region = MKCoordinateRegion(
                center: focusedMarker.coordinate,
                span: MKCoordinateSpan(latitudeDelta: 0.016, longitudeDelta: 0.016)
            )
            return
        }

        if focusMode == .userLocation, let userCoordinate {
            region = MKCoordinateRegion(
                center: userCoordinate,
                span: MKCoordinateSpan(latitudeDelta: 0.022, longitudeDelta: 0.022)
            )
            return
        }

        guard let first = markers.first else {
            let fallbackCenter = userCoordinate ?? NearbyPlaceLoader.defaultCenter
            region = MKCoordinateRegion(
                center: fallbackCenter,
                span: MKCoordinateSpan(latitudeDelta: 0.35, longitudeDelta: 0.35)
            )
            return
        }

        if focusMode == .newestOnly {
            if let newestMarker = markers.max(by: { $0.createdAt < $1.createdAt }) {
                region = MKCoordinateRegion(
                    center: newestMarker.coordinate,
                    span: MKCoordinateSpan(latitudeDelta: 0.020, longitudeDelta: 0.020)
                )
                return
            }
        }

        if focusMode == .recentBalanced || focusMode == .nearbyRecent {
            let target = bestMarkerForBalancedMode(mode: focusMode)
            region = MKCoordinateRegion(
                center: target.coordinate,
                span: MKCoordinateSpan(latitudeDelta: 0.018, longitudeDelta: 0.018)
            )
            return
        }

        if markers.count == 1 {
            region = MKCoordinateRegion(
                center: first.coordinate,
                span: MKCoordinateSpan(latitudeDelta: 0.022, longitudeDelta: 0.022)
            )
            return
        }

        let latitudes = markers.map { $0.coordinate.latitude }
        let longitudes = markers.map { $0.coordinate.longitude }
        let minLat = latitudes.min() ?? first.coordinate.latitude
        let maxLat = latitudes.max() ?? first.coordinate.latitude
        let minLon = longitudes.min() ?? first.coordinate.longitude
        let maxLon = longitudes.max() ?? first.coordinate.longitude

        let center = CLLocationCoordinate2D(
            latitude: (minLat + maxLat) / 2,
            longitude: (minLon + maxLon) / 2
        )

        let maxSpan = max(maxLat - minLat, maxLon - minLon)
        let delta: CLLocationDegrees
        switch maxSpan {
        case ..<0.02: delta = 0.028
        case ..<0.05: delta = 0.06
        case ..<0.12: delta = 0.15
        case ..<0.30: delta = 0.32
        case ..<0.80: delta = 0.82
        default: delta = 1.55
        }

        region = MKCoordinateRegion(
            center: center,
            span: MKCoordinateSpan(latitudeDelta: delta, longitudeDelta: delta)
        )
    }

    private func bestMarkerForBalancedMode(mode: MapFocusMode) -> MapPostMarker {
        guard let userCoordinate else {
            return markers.max(by: { $0.createdAt < $1.createdAt }) ?? markers[0]
        }

        let now = Date().timeIntervalSince1970
        let maxRecencyWindow: TimeInterval = 86_400
        let maxDistanceMiles: Double = 25

        let weighted = markers.map { marker -> (marker: MapPostMarker, score: Double) in
            let ageSeconds = max(0, now - marker.createdAt.timeIntervalSince1970)
            let recencyScore = max(0.0, 1.0 - min(ageSeconds / maxRecencyWindow, 1.0))
            let distance = NearbyPlaceLoader.haversineMiles(from: userCoordinate, to: marker.coordinate)
            let distanceScore = max(0.0, 1.0 - min(distance / maxDistanceMiles, 1.0))

            let (recencyWeight, distanceWeight): (Double, Double) = {
                switch mode {
                case .recentBalanced:
                    return (0.72, 0.28)
                case .nearbyRecent:
                    return (0.50, 0.50)
                default:
                    return (1.0, 0.0)
                }
            }()

            return (marker, recencyScore * recencyWeight + distanceScore * distanceWeight)
        }

        return weighted.max(by: { $0.score < $1.score })?.marker ?? markers[0]
    }
}

final class LocationService: NSObject, ObservableObject, CLLocationManagerDelegate {
    @Published var authorizationStatus: CLAuthorizationStatus
    @Published var lastKnownLocation: CLLocation? = nil

    private let manager: CLLocationManager

    override init() {
        let locationManager = CLLocationManager()
        self.manager = locationManager
        self.authorizationStatus = locationManager.authorizationStatus
        super.init()
        locationManager.delegate = self
        locationManager.desiredAccuracy = kCLLocationAccuracyHundredMeters
    }

    func requestPermission() {
        switch manager.authorizationStatus {
        case .notDetermined:
            manager.requestWhenInUseAuthorization()
        case .authorizedWhenInUse, .authorizedAlways:
            manager.requestLocation()
        case .denied, .restricted:
            if let settingsURL = URL(string: UIApplication.openSettingsURLString) {
                UIApplication.shared.open(settingsURL)
            }
        @unknown default:
            break
        }
    }

    func locationManager(_ manager: CLLocationManager, didUpdateLocations locations: [CLLocation]) {
        lastKnownLocation = locations.last
    }

    func locationManager(_ manager: CLLocationManager, didChangeAuthorization status: CLAuthorizationStatus) {
        authorizationStatus = status
        if status == .authorizedWhenInUse || status == .authorizedAlways {
            manager.requestLocation()
        }
    }

    func locationManager(_ manager: CLLocationManager, didFailWithError error: Error) {
        lastKnownLocation = nil
    }
}

private struct RouteMapPoint: Identifiable {
    let id: String
    let name: String
    let coordinate: CLLocationCoordinate2D
    let tint: Color
}

private enum LiveRouteCodec {
    static func encode(start: String, end: String, isRunBranding: Bool = false) -> String {
        var components = URLComponents()
        components.scheme = "spotroute"
        components.host = "route"
        components.queryItems = [
            URLQueryItem(name: "start", value: start.trimmingCharacters(in: .whitespacesAndNewlines)),
            URLQueryItem(name: "end", value: end.trimmingCharacters(in: .whitespacesAndNewlines)),
            URLQueryItem(name: "brand", value: isRunBranding ? "run" : "trip")
        ]
        return components.string ?? "spotroute://route"
    }

    static func decode(_ raw: String) -> (start: String, end: String, isRunBranding: Bool)? {
        guard let components = URLComponents(string: raw), components.scheme == "spotroute" else {
            return nil
        }

        let start = components.queryItems?.first(where: { $0.name == "start" })?.value?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let end = components.queryItems?.first(where: { $0.name == "end" })?.value?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let brand = components.queryItems?.first(where: { $0.name == "brand" })?.value?.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() ?? "trip"
        let isRunBranding = brand == "run"

        guard !start.isEmpty || !end.isEmpty else { return nil }
        return (start: start, end: end, isRunBranding: isRunBranding)
    }

    static func resolvedMapPoints(start: String, end: String, nearbyPlaces: [NearbyPlace]) -> [RouteMapPoint] {
        let trimmedStart = start.trimmingCharacters(in: .whitespacesAndNewlines)
        let trimmedEnd = end.trimmingCharacters(in: .whitespacesAndNewlines)

        var points: [RouteMapPoint] = []
        if !trimmedStart.isEmpty {
            let coordinate = coordinateForPlace(named: trimmedStart, nearbyPlaces: nearbyPlaces)
            points.append(RouteMapPoint(id: "start-\(trimmedStart)", name: trimmedStart, coordinate: coordinate, tint: .green))
        }
        if !trimmedEnd.isEmpty {
            let coordinate = coordinateForPlace(named: trimmedEnd, nearbyPlaces: nearbyPlaces)
            points.append(RouteMapPoint(id: "end-\(trimmedEnd)", name: trimmedEnd, coordinate: coordinate, tint: .red))
        }
        return points
    }

    static func region(for points: [RouteMapPoint]) -> MKCoordinateRegion {
        guard let first = points.first else {
            return MKCoordinateRegion(
                center: NearbyPlaceLoader.defaultCenter,
                span: MKCoordinateSpan(latitudeDelta: 0.18, longitudeDelta: 0.18)
            )
        }

        if points.count == 1 {
            return MKCoordinateRegion(
                center: first.coordinate,
                span: MKCoordinateSpan(latitudeDelta: 0.14, longitudeDelta: 0.14)
            )
        }

        let latitudes = points.map { $0.coordinate.latitude }
        let longitudes = points.map { $0.coordinate.longitude }
        let minLat = latitudes.min() ?? first.coordinate.latitude
        let maxLat = latitudes.max() ?? first.coordinate.latitude
        let minLon = longitudes.min() ?? first.coordinate.longitude
        let maxLon = longitudes.max() ?? first.coordinate.longitude

        let center = CLLocationCoordinate2D(
            latitude: (minLat + maxLat) / 2,
            longitude: (minLon + maxLon) / 2
        )
        let span = MKCoordinateSpan(
            latitudeDelta: max(0.08, (maxLat - minLat) * 1.9),
            longitudeDelta: max(0.08, (maxLon - minLon) * 1.9)
        )

        return MKCoordinateRegion(center: center, span: span)
    }

    private static func coordinateForPlace(named place: String, nearbyPlaces: [NearbyPlace]) -> CLLocationCoordinate2D {
        let normalized = place.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        if let local = nearbyPlaces.first(where: { $0.name.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() == normalized }) {
            return CLLocationCoordinate2D(latitude: local.latitude, longitude: local.longitude)
        }

        let fallbackPool = NearbyPlaceLoader.loadAllPlaces(from: NearbyPlaceLoader.defaultCenter, limit: 240)
        if let known = fallbackPool.first(where: { $0.name.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() == normalized }) {
            return CLLocationCoordinate2D(latitude: known.latitude, longitude: known.longitude)
        }

        let hashSeed = abs(normalized.hashValue % 1000)
        let latOffset = Double(hashSeed % 35) / 1000.0
        let lonOffset = Double((hashSeed / 7) % 35) / 1000.0
        return CLLocationCoordinate2D(
            latitude: NearbyPlaceLoader.defaultCenter.latitude + latOffset,
            longitude: NearbyPlaceLoader.defaultCenter.longitude - lonOffset
        )
    }
}

private enum GuidePostCodec {
    static func encode(steps: [String]) -> String {
        let cleanedSteps = normalizedSteps(steps)
        var components = URLComponents()
        components.scheme = "spotguide"
        components.host = "slides"
        components.queryItems = cleanedSteps.enumerated().map { pair in
            URLQueryItem(name: "s\(pair.offset + 1)", value: pair.element)
        }
        return components.string ?? "spotguide://slides"
    }

    static func decode(_ raw: String) -> [String] {
        guard let components = URLComponents(string: raw), components.scheme == "spotguide" else {
            return []
        }

        let keyed = (components.queryItems ?? [])
            .filter { $0.name.hasPrefix("s") }
            .compactMap { item -> (Int, String)? in
                let indexRaw = String(item.name.dropFirst())
                guard let index = Int(indexRaw), index >= 1, index <= 10 else { return nil }
                let value = item.value?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
                guard !value.isEmpty else { return nil }
                return (index, value)
            }
            .sorted { $0.0 < $1.0 }

        return normalizedSteps(keyed.map { $0.1 })
    }

    static func normalizedSteps(_ steps: [String]) -> [String] {
        let cleaned = steps
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
        return Array(cleaned.prefix(10))
    }
}

private struct WorkPostDetails {
    let listings: [String]
    let phone: String
    let email: String
    let dmResume: Bool
}

private enum WorkPostCodec {
    static func encode(listings: [String], phone: String, email: String, dmResume: Bool) -> String {
        let cleanedListings = normalizedListings(listings)
        var components = URLComponents()
        components.scheme = "spotwork"
        components.host = "listing"

        var items: [URLQueryItem] = cleanedListings.enumerated().map { pair in
            URLQueryItem(name: "j\(pair.offset + 1)", value: pair.element)
        }
        items.append(URLQueryItem(name: "phone", value: phone.trimmingCharacters(in: .whitespacesAndNewlines)))
        items.append(URLQueryItem(name: "email", value: email.trimmingCharacters(in: .whitespacesAndNewlines)))
        items.append(URLQueryItem(name: "dmresume", value: dmResume ? "1" : "0"))
        components.queryItems = items

        return components.string ?? "spotwork://listing"
    }

    static func decode(_ raw: String) -> WorkPostDetails? {
        guard let components = URLComponents(string: raw), components.scheme == "spotwork" else {
            return nil
        }

        let listings = normalizedListings(
            (components.queryItems ?? [])
                .filter { $0.name.hasPrefix("j") }
                .compactMap { item -> (Int, String)? in
                    let rawIndex = String(item.name.dropFirst())
                    guard let index = Int(rawIndex), index >= 1, index <= 10 else { return nil }
                    let value = item.value?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
                    guard !value.isEmpty else { return nil }
                    return (index, value)
                }
                .sorted { $0.0 < $1.0 }
                .map { $0.1 }
        )

        let phone = components.queryItems?.first(where: { $0.name == "phone" })?.value?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let email = components.queryItems?.first(where: { $0.name == "email" })?.value?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let dmResume = components.queryItems?.first(where: { $0.name == "dmresume" })?.value == "1"

        if listings.isEmpty && phone.isEmpty && email.isEmpty {
            return nil
        }

        return WorkPostDetails(listings: listings, phone: phone, email: email, dmResume: dmResume)
    }

    static func normalizedListings(_ listings: [String]) -> [String] {
        let cleaned = listings
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
        return Array(cleaned.prefix(10))
    }

    static func sanitizedPhoneDigits(_ raw: String) -> String {
        raw.filter { $0.isWholeNumber }
    }
}

private struct SaleDraftPersistence: Codable {
    enum CodingKeys: String, CodingKey {
        case item, price, phone, email, description, photoData, photoDatas
    }

    let item: String
    let price: String
    let phone: String
    let email: String
    let description: String
    let photoData: Data?
    let photoDatas: [Data]

    init(item: String, price: String, phone: String, email: String, description: String, photoData: Data?, photoDatas: [Data]) {
        self.item = item
        self.price = price
        self.phone = phone
        self.email = email
        self.description = description
        self.photoData = photoData
        self.photoDatas = photoDatas
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        item = try container.decodeIfPresent(String.self, forKey: .item) ?? ""
        price = try container.decodeIfPresent(String.self, forKey: .price) ?? ""
        phone = try container.decodeIfPresent(String.self, forKey: .phone) ?? ""
        email = try container.decodeIfPresent(String.self, forKey: .email) ?? ""
        description = try container.decodeIfPresent(String.self, forKey: .description) ?? ""
        photoData = try container.decodeIfPresent(Data.self, forKey: .photoData)
        photoDatas = try container.decodeIfPresent([Data].self, forKey: .photoDatas) ?? []
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(item, forKey: .item)
        try container.encode(price, forKey: .price)
        try container.encode(phone, forKey: .phone)
        try container.encode(email, forKey: .email)
        try container.encode(description, forKey: .description)
        try container.encodeIfPresent(photoData, forKey: .photoData)
        try container.encode(photoDatas, forKey: .photoDatas)
    }
}

struct SalePostDetails {
    let items: [String]
    let price: String
    let phone: String
    let email: String
}

enum SalePostCodec {
    static func encode(items: [String], price: String, phone: String, email: String) -> String {
        let cleanedItems = normalizedItems(items)
        var components = URLComponents()
        components.scheme = "spotsale"
        components.host = "listing"

        var queryItems: [URLQueryItem] = cleanedItems.enumerated().map { pair in
            URLQueryItem(name: "i\(pair.offset + 1)", value: pair.element)
        }
        queryItems.append(URLQueryItem(name: "price", value: price.trimmingCharacters(in: .whitespacesAndNewlines)))
        queryItems.append(URLQueryItem(name: "phone", value: phone.trimmingCharacters(in: .whitespacesAndNewlines)))
        queryItems.append(URLQueryItem(name: "email", value: email.trimmingCharacters(in: .whitespacesAndNewlines)))
        components.queryItems = queryItems

        return components.string ?? "spotsale://listing"
    }

    static func decode(_ raw: String) -> SalePostDetails? {
        guard let components = URLComponents(string: raw), components.scheme == "spotsale" else {
            return nil
        }

        let items = normalizedItems(
            (components.queryItems ?? [])
                .filter { $0.name.hasPrefix("i") }
                .compactMap { pair -> (Int, String)? in
                    let indexValue = String(pair.name.dropFirst())
                    guard let index = Int(indexValue), index >= 1, index <= 10 else { return nil }
                    let value = pair.value?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
                    guard !value.isEmpty else { return nil }
                    return (index, value)
                }
                .sorted { $0.0 < $1.0 }
                .map { $0.1 }
        )

        let price = components.queryItems?.first(where: { $0.name == "price" })?.value?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let phone = components.queryItems?.first(where: { $0.name == "phone" })?.value?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let email = components.queryItems?.first(where: { $0.name == "email" })?.value?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""

        guard !items.isEmpty || !price.isEmpty || !phone.isEmpty || !email.isEmpty else {
            return nil
        }

        return SalePostDetails(items: items, price: price, phone: phone, email: email)
    }

    static func normalizedItems(_ items: [String]) -> [String] {
        let cleaned = items
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
        return Array(cleaned.prefix(10))
    }
}

private enum SongPostRules {
    static let allowedExtensions: Set<String> = ["mp3", "m4a", "aac", "wav", "aif", "aiff", "flac"]

    static func isSupported(_ url: URL) -> Bool {
        let ext = url.pathExtension.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        return allowedExtensions.contains(ext)
    }

    static func allowedFormatsText() -> String {
        "Supported song files: .mp3, .m4a, .aac, .wav, .aiff, .flac"
    }

    static func embeddedArtworkImage(from url: URL?) -> UIImage? {
        guard let url else { return nil }

        let asset = AVAsset(url: url)
        let metadataItems = asset.commonMetadata.filter { item in
            guard let key = item.commonKey else { return false }
            return key == .commonKeyArtwork || key == .commonKeyTitle || key == .commonKeyAlbumName
        }

        for item in metadataItems {
            if let data = item.value as? Data,
               let image = UIImage(data: data) {
                return image
            }

            if let value = item.value,
               let image = UIImage(data: value as? Data ?? Data()) {
                return image
            }
        }

        for item in asset.metadata {
            guard let key = item.commonKey,
                  key == .commonKeyArtwork else {
                continue
            }

            if let data = item.value as? Data,
               let image = UIImage(data: data) {
                return image
            }
        }

        for item in asset.metadata {
            guard let key = item.key as? String else { continue }
            let isArtworkKey = key == "com.apple.iTunesArtwork" || key == "artwork"
            guard isArtworkKey else { continue }
            if let data = item.value as? Data,
               let image = UIImage(data: data) {
                return image
            }
        }

        return nil
    }
}

