enum LocationSuggestionRanker {
    static func rankedSuggestions(
        query: String,
        nearbyPlaces: [NearbyPlace],
        fallback: [String],
        userCoordinate: CLLocationCoordinate2D
    ) -> [String] {
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()

        let nearbyMatches: [String]
        if trimmed.isEmpty {
            nearbyMatches = nearbyPlaces
                .sorted { lhs, rhs in
                    let lhsDistance = NearbyPlaceLoader.haversineMiles(
                        from: userCoordinate,
                        to: CLLocationCoordinate2D(latitude: lhs.latitude, longitude: lhs.longitude)
                    )
                    let rhsDistance = NearbyPlaceLoader.haversineMiles(
                        from: userCoordinate,
                        to: CLLocationCoordinate2D(latitude: rhs.latitude, longitude: rhs.longitude)
                    )
                    return lhsDistance < rhsDistance
                }
                .prefix(50)
                .map(\.name)
        } else {
            nearbyMatches = nearbyPlaces
                .map { place -> (name: String, score: Double) in
                    let lower = place.name.lowercased()
                    let distance = NearbyPlaceLoader.haversineMiles(
                        from: userCoordinate,
                        to: CLLocationCoordinate2D(latitude: place.latitude, longitude: place.longitude)
                    )

                    let isQueryMatch = lower == trimmed
                        || lower.hasPrefix(trimmed)
                        || lower.contains(trimmed)
                        || place.category.lowercased().contains(trimmed)
                    guard isQueryMatch else {
                        return (place.name, 0)
                    }

                    let textScore: Double = {
                        var score = 0.0
                        if lower == trimmed { score += 100000 }
                        if lower.hasPrefix(trimmed) { score += 60000 }
                        if lower.contains(trimmed) { score += 25000 }
                        if place.category.lowercased().contains(trimmed) { score += 15000 }
                        return score
                    }()

                    let proximityScore = max(0.0, 50.0 - (distance * 0.5))
                    let combinedScore = textScore + proximityScore
                    return (place.name, combinedScore)
                }
                .filter { $0.score > 0 }
                .sorted { lhs, rhs in
                    if lhs.score != rhs.score { return lhs.score > rhs.score }
                    let lhsDistance = distanceForPlace(named: lhs.name, nearbyPlaces: nearbyPlaces, userCoordinate: userCoordinate)
                    let rhsDistance = distanceForPlace(named: rhs.name, nearbyPlaces: nearbyPlaces, userCoordinate: userCoordinate)
                    return lhsDistance < rhsDistance
                }
                .map(\.name)
        }

        let fallbackMatches = fallback
            .map { suggestion -> (name: String, score: Double) in
                let lower = suggestion.lowercased()
                let textScore = fallbackScore(for: suggestion, query: trimmed)
                return (suggestion, textScore)
            }
            .filter { suggestion in
                if trimmed.isEmpty { return true }
                let lower = suggestion.name.lowercased()
                return lower.contains(trimmed) || lower.hasPrefix(trimmed) || lower == trimmed
            }
            .sorted { lhs, rhs in
                if lhs.score != rhs.score { return lhs.score > rhs.score }
                return lhs.name < rhs.name
            }
            .map(\.name)

        var ordered: [String] = []
        for name in nearbyMatches + fallbackMatches {
            if !ordered.contains(name) {
                ordered.append(name)
            }
        }

        return ordered
    }

    private static func distanceForPlace(
        named name: String,
        nearbyPlaces: [NearbyPlace],
        userCoordinate: CLLocationCoordinate2D
    ) -> Double {
        guard let place = nearbyPlaces.first(where: { $0.name == name }) else {
            return Double.greatestFiniteMagnitude
        }

        return NearbyPlaceLoader.haversineMiles(
            from: userCoordinate,
            to: CLLocationCoordinate2D(latitude: place.latitude, longitude: place.longitude)
        )
    }

    private static func fallbackScore(for suggestion: String, query: String) -> Double {
        let lower = suggestion.lowercased()
        if query.isEmpty { return 1 }
        if lower == query { return 100000 }
        if lower.hasPrefix(query) { return 60000 }
        if lower.contains(query) { return 25000 }
        return 0
    }
}

struct ContentView: View {
    @Environment(\.scenePhase) private var scenePhase
    @Environment(\.openURL) private var openURL

    static let usernameGoldColor = Color.black

    private struct EngagementSnapshot: Codable {
        var viewCount: Int
        var timeViewedSeconds: Int
        var savedCount: Int
        var shareCount: Int
        var likes: Int
        var peakEngagementScore: Double
    }

    private struct SavedAccountCredential: Codable, Identifiable {
        let email: String
        var username: String
        var displayName: String
        var profilePhotoURL: String?
        var password: String
        var lastUsedAt: TimeInterval

        var id: String {
            let normalizedUsername = FirebaseSpotService.normalizeUsername(username)
            if !normalizedUsername.isEmpty {
                return normalizedUsername.lowercased()
            }
            let trimmedEmail = email.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            return trimmedEmail.isEmpty ? "anonymous" : trimmedEmail
        }

        init(
            email: String,
            username: String,
            displayName: String,
            profilePhotoURL: String? = nil,
            password: String = "",
            lastUsedAt: TimeInterval
        ) {
            self.email = email
            self.username = username
            self.displayName = displayName
            self.profilePhotoURL = profilePhotoURL
            self.password = password
            self.lastUsedAt = lastUsedAt
        }
    }

    static func savedAccountIdentityKey(username: String, email: String) -> String {
        let normalizedUsername = FirebaseSpotService.normalizeUsername(username)
        if !normalizedUsername.isEmpty {
            return normalizedUsername.lowercased()
        }

        let trimmedEmail = email.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        if !trimmedEmail.isEmpty {
            return trimmedEmail
        }

        return "anonymous"
    }

    static func preferredProfilePhotoURL(candidateRemoteURL: String?, savedAccountPhotoURL: String?, fallbackLocalValue: String? = nil) -> String {
        let candidate = candidateRemoteURL?.trimmingCharacters(in: .whitespacesAndNewlines)
        if let candidate, !candidate.isEmpty {
            return candidate
        }

        let savedValue = savedAccountPhotoURL?.trimmingCharacters(in: .whitespacesAndNewlines)
        if let savedValue, !savedValue.isEmpty {
            return savedValue
        }

        let fallbackValue = fallbackLocalValue?.trimmingCharacters(in: .whitespacesAndNewlines)
        if let fallbackValue, !fallbackValue.isEmpty {
            return fallbackValue
        }

        return ""
    }

    static func canonicalProfilePhotoURL(fetchedRemoteURL: String?, fallbackProfilePhotoURL: String?, localProfilePhotoURL: String? = nil) -> String {
        let fetched = (fetchedRemoteURL ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        if !fetched.isEmpty {
            return fetched
        }

        let fallback = (fallbackProfilePhotoURL ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        if !fallback.isEmpty {
            return fallback
        }

        let local = (localProfilePhotoURL ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        if !local.isEmpty {
            return local
        }

        return ""
    }

    static func shouldSyncLocalProfilePhotoToCloud(
        fetchedRemoteURL: String?,
        cachedLocalPhotoExists: Bool,
        hasPendingSync: Bool,
        hasRemovalPending: Bool,
        isUploadInFlight: Bool
    ) -> Bool {
        let remoteURL = (fetchedRemoteURL ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        return remoteURL.isEmpty
            && cachedLocalPhotoExists
            && !hasPendingSync
            && !hasRemovalPending
            && !isUploadInFlight
    }

    static func preferredAccountUsername(storedUsername: String?, firebaseUsername: String?) -> String {
        let normalizedStored = FirebaseSpotService.normalizeUsername(storedUsername ?? "")
        if !normalizedStored.isEmpty && normalizedStored != "user" {
            return normalizedStored
        }

        let normalizedFirebase = FirebaseSpotService.normalizeUsername(firebaseUsername ?? "")
        if !normalizedFirebase.isEmpty && normalizedFirebase != "user" {
            return normalizedFirebase
        }

        if !normalizedStored.isEmpty {
            return normalizedStored
        }

        return normalizedFirebase
    }

