                                .foregroundStyle(.primary)
                                .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
                        }
                        .buttonStyle(.plain)

                        Button {
                            draftPhotoCropScale = 1.0
                            draftPhotoCropOffset = .zero
                            currentScreen = .composer
