                VStack(alignment: .center, spacing: 18) {
                    RoundedRectangle(cornerRadius: 22)
                        .fill(LinearGradient(colors: [Color("spotBlue"), Color.purple], startPoint: .topLeading, endPoint: .bottomTrailing))
                        .frame(maxWidth: .infinity)
                        .frame(height: 420)
