                    PhotosPicker(selection: $draftPhotoItem, matching: .images, photoLibrary: .shared()) {
                        Text("Choose photo")
                            .font(.headline.weight(.semibold))
                            .frame(maxWidth: .infinity)
                            .padding(.vertical, 14)
                            .foregroundStyle(.white)
                            .background(Color.black)
                            .clipShape(Capsule())
