struct ShimmerModifier: ViewModifier {
    @State private var shimmerPosition: CGFloat = -1.0
    @State private var animationTask: Task<Void, Never>? = nil

    func body(content: Content) -> some View {
        content
            .overlay(
                GeometryReader { geo in
                    let bandWidth = max(geo.size.width * 0.6, 32.0)
                    let travel = max(geo.size.width + bandWidth, 120.0)

                    LinearGradient(
                        colors: [Color.clear, Color.white.opacity(0.55), Color.clear],
                        startPoint: .leading,
                        endPoint: .trailing
                    )
                    .frame(width: bandWidth)
                    .offset(x: shimmerPosition * travel * 0.5)
                    .animation(.easeInOut(duration: 1.1), value: shimmerPosition)
                    .onAppear {
                        animationTask?.cancel()
                        shimmerPosition = -1.0
                        withAnimation(.easeInOut(duration: 1.1)) {
                            shimmerPosition = 1.0
                        }
                        animationTask = Task {
                            try? await Task.sleep(nanoseconds: UInt64(1_100_000_000))
                            guard !Task.isCancelled else { return }
                            await MainActor.run {
                                shimmerPosition = -1.0
                            }
                        }
                    }
                    .onDisappear {
                        animationTask?.cancel()
                        animationTask = nil
                        shimmerPosition = -1.0
                    }
                }
            )
            .mask(content)
    }
}

enum PollVoteLogic {
    static func updatedVotes(
        currentVotes: [Int],
        previousSelection: Int?,
        nextSelection: Int
    ) -> (votes: [Int], selected: Int?) {
        let safeVotes = currentVotes.count >= 2 ? currentVotes : [0, 0]
        guard nextSelection >= 0, nextSelection < safeVotes.count else {
            return (safeVotes, previousSelection)
        }

        var updated = safeVotes
        if updated.indices.contains(nextSelection) {
            updated[nextSelection] = min(Int.max, max(0, updated[nextSelection]) + 1)
        }
        return (updated, nextSelection)
    }
}

